'use strict';
const fmt = n => n === null ? 'No publicado' : new Intl.NumberFormat('es-ES', {maximumFractionDigits: 2}).format(n);
const source = (page, label = `Fuente · p. ${page}`) => `<a class="source-link" href="plan-nextil-2026-2030.pdf#page=${page}" target="_blank" rel="noopener">${label}</a>`;
const reportSource = (page, label = `Informe 1S · p. ${page}`) => `<a class="source-link" href="resultados-1s-2026.pdf#page=${page}" target="_blank" rel="noopener">${label}</a>`;
const escapeHTML = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
let plan;
function renderSnapshot(){
 const r=plan.report;
 document.getElementById('results-snapshot').innerHTML=`<div class="results-grid"><article class="result-card"><span>Ventas · 1S 2026</span><strong>${fmt(r.normalized.sales)} <small>M€</small></strong><span>Normalizadas ${reportSource(5)}</span><div class="result-compare"><span>Perímetro comparable</span><b>${fmt(r.comparable.sales)} M€</b><span>Guidance anual 2026</span><b>${fmt(plan.years[0].sales)} M€</b></div></article><article class="result-card"><span>EBITDA · 1S 2026</span><strong>${fmt(r.normalized.ebitda)} <small>M€</small></strong><span>Normalizado ${reportSource(5)}</span><div class="result-compare"><span>Perímetro comparable</span><b>${fmt(r.comparable.ebitda)} M€</b><span>Guidance anual 2026</span><b>${fmt(plan.years[0].ebitda)} M€</b></div></article><article class="result-card result-good"><span>Deuda neta / EBITDA</span><strong>${fmt(r.leverage)}<small>x</small></strong><span>Al cierre de junio ${reportSource(9)}</span><div class="result-compare"><span>Límite del plan</span><b>&lt;2,5x</b><span>Deuda neta</span><b>${fmt(r.debt)} M€</b></div><span class="result-state">Dentro del límite al cierre</span></article></div><p class="results-basis">Normalizado: incluye Sindutex desde enero; excluye otras tres adquisiciones previstas. El semestre no determina el cumplimiento anual. Ratio de deuda calculado con EBITDA de los últimos 12 meses. ${reportSource(17,'Criterio del informe · p. 17')}</p>`;
}
function renderYear(year, focus = false) {
 const y = plan.years.find(item => item.year === year);
 document.querySelectorAll('[role="tab"]').forEach(button => {const selected = Number(button.dataset.year) === year;button.setAttribute('aria-selected', String(selected));button.tabIndex = selected ? 0 : -1;if(selected && focus)button.focus();});
 const metrics = [['Ventas',y.sales],['EBITDA',y.ebitda],['Inversión ≈',y.investment]].map(([label,n])=>`<div><small>${label}</small><strong class="${n===null?'unpublished':''}">${fmt(n)}${n===null?'':'<span> M€</span>'}</strong></div>`).join('');
 const allocation = y.sales === null ? '<p class="financial-foot">Sin desglose de ventas ni EBITDA por hub publicado para este año. No se han interpolado cifras.</p>' : `<div class="allocation"><div class="allocation-labels"><span>Europa · ${fmt(y.euSales)} M€</span><span>América · ${fmt(y.usSales)} M€</span></div><div class="allocation-bar" role="img" aria-label="Ventas previstas: Europa ${y.euSales} millones de euros; América ${y.usSales} millones de euros"><i style="width:${y.euSales/y.sales*100}%"></i><i style="width:${y.usSales/y.sales*100}%"></i></div><div class="allocation-labels"><span>EBITDA · ${fmt(y.euEbitda)} M€</span><span>EBITDA · ${fmt(y.usEbitda)} M€</span></div></div>`;
 const panel = document.getElementById('year-panel');panel.setAttribute('aria-labelledby',`tab-${year}`);
 panel.innerHTML = `<div class="year-panel"><div class="year-financial"><div class="year-top"><h3>${y.title}</h3><span class="pill">${y.type} ${year}</span></div><div class="annual-metrics">${metrics}</div>${allocation}<div class="debt-row"><span>DFN / EBITDA previsto</span><strong>${y.ratio === null ? 'No publicado' : fmt(y.ratio)+'x'}</strong></div><p class="financial-foot">Deuda neta prevista: ${y.debt===null?'no publicada':'≈'+fmt(y.debt)+' M€'}. Límite del plan: &lt;2,5x.</p><p class="financial-foot">${source(28,'Ventas y EBITDA · pp. 28–31')} · ${source(32,'Inversión · p. 32')} · ${source(33,'Deuda · p. 33')}</p><p class="financial-foot">Previsiones normalizadas. ${year===2030?'Cifras aproximadas para 2030. ':''}${year===2026 ? `1S 2026: ${fmt(plan.report.normalized.sales)} M€ de ventas y ${fmt(plan.report.normalized.ebitda)} M€ de EBITDA normalizados. ${reportSource(5)} <a class="source-link" href="#objectives">Ver seguimiento</a>` : 'Sin resultados de este ejercicio incorporados.'}</p></div><div class="year-events"><p class="eyebrow">HITOS PUBLICADOS</p>${y.items.map(([title,body,page])=>`<article class="event"><h4>${title}</h4><p>${body}</p>${source(page)}</article>`).join('')}${plan.updates.filter(u=>u.year===year).length ? `<div class="reported-updates"><p class="eyebrow">ACTUALIZACIÓN · 30 SEP 2026</p>${plan.updates.filter(u=>u.year===year).map(u=>`<article><h4>${u.title}</h4><p>${u.body} ${reportSource(u.page)}</p></article>`).join('')}</div>` : ''}</div></div>`;
}
function showDetail(index){
 const item=plan.objectives[index], evidence=plan.tracking[index];
 document.getElementById('detail-title').textContent=item[0];
 document.getElementById('detail-value').textContent=item[1];
 document.getElementById('detail-text').textContent=item[4];
 document.getElementById('detail-status').textContent=evidence.status;
 document.getElementById('detail-evidence').textContent=evidence.note;
 const reportLink=document.getElementById('detail-report');reportLink.hidden=evidence.page===null;
 if(evidence.page){reportLink.href=`resultados-1s-2026.pdf#page=${evidence.page}`;reportLink.textContent=`Informe 1S 2026 · página ${evidence.page}`;}
 document.getElementById('detail-source').href=`plan-nextil-2026-2030.pdf#page=${item[3]}`;
 document.getElementById('detail-source').textContent=`Plan estratégico · página ${item[3]}`;
 document.getElementById('detail-dialog').showModal();
}
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw new Error('Datos no disponibles');plan=await response.json();
 document.getElementById('year-tabs').innerHTML=plan.years.map(y=>`<button role="tab" id="tab-${y.year}" aria-controls="year-panel" aria-selected="false" tabindex="-1" data-year="${y.year}"><strong>${y.year}</strong><span>${y.type}</span></button>`).join('');
 document.getElementById('year-tabs').addEventListener('click',event=>{const button=event.target.closest('button');if(button)renderYear(Number(button.dataset.year));});
 document.getElementById('year-tabs').addEventListener('keydown',event=>{const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(event.key))return;const current=plan.years.findIndex(y=>String(y.year)===event.target.dataset.year);if(current<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?4:(current+(event.key==='ArrowRight'?1:4))%5;renderYear(plan.years[next].year,true);});
 document.getElementById('objectives-body').innerHTML=plan.objectives.map((o,i)=>{const t=plan.tracking[i];return `<tr><td>${o[0]}</td><td>${escapeHTML(o[1])}</td><td>${o[2]}</td><td class="latest-cell">${escapeHTML(t.value)}${t.page?`<br>${reportSource(t.page)}`:''}</td><td><span class="status ${t.tone}">${t.status}</span></td><td><button data-detail="${i}" aria-label="Ver detalle: ${o[0]}">Ver detalle</button></td></tr>`}).join('');
 document.getElementById('objectives-body').addEventListener('click',event=>{const button=event.target.closest('button[data-detail]');if(button)showDetail(Number(button.dataset.detail));});
 document.getElementById('pillars').innerHTML=plan.pillars.map((p,i)=>`<article class="pillar"><span class="place">${p.place}</span><h3>${p.name}</h3><p class="goal">${p.goal}</p>${p.cagr?`<div class="hub-numbers"><div><strong>${p.cagr}</strong><span>CAGR orgánico</span></div><div><strong>≈${p.sales}</strong><span>Ventas 2030 · M€</span></div><div><strong>≈${p.ebitda}</strong><span>EBITDA 2030 · M€</span></div></div>`:'<p class="pill">Greendyes® · Circularidad · Trazabilidad</p>'}<ul>${p.items.map(item=>`<li>${item}</li>`).join('')}</ul><div class="pillar-update"><span class="eyebrow">AVANCE PUBLICADO</span><p>${p.update.text}</p>${reportSource(p.update.page)}</div>${source(p.page)}${i<2?' · '+source(22,'CAGR · p. 22')+' · '+source(30,'Metas · pp. 30–31'):''}</article>`).join('');
 renderSnapshot();
 renderYear(2026);
 }catch(error){document.getElementById('year-panel').innerHTML='<p role="alert">No se han podido cargar los datos del plan. Recarga la página o consulta el PDF original.</p>';console.error(error);}}
const dialog=document.getElementById('detail-dialog');dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
init();
